%----------------------
\section*{{Professional Experience}}

\noindent\textbf{{Staff Machine Learning Engineer}} \hfill \textbf{{******}}\\
\textit{{San Francisco, CA}} \hfill \textit{{Feb 2025 -- Present}}
\begin{{itemize}}
    \item Lead ML efforts on fraud detection systems processing over 500M transactions per month.
    \item Architected a real-time feature store reducing model inference latency by 40\%.
\end{{itemize}}

\vspace{{3pt}}

\noindent\textbf{{Senior Machine Learning Engineer}} \hfill \textbf{{*****}}\\
\textit{{Mountain View, CA}} \hfill \textit{{Apr 2023 -- Jan 2025}}
